<section><h1 class="h3 mb-3">支付结果</h1><div class="card p-4"><p>流水号：<span class="mono"><?= h($pay['trade_no']) ?></span></p><p>金额：<strong><?= money($pay['amount']) ?></strong></p><p id="pay-status" class="alert alert-info">当前状态：<?= (int)$pay['status'] === 1 ? '已支付' : '待确认' ?></p><?php if (isset($action['type']) && $action['type'] === 'manual'): ?><div class="alert alert-warning"><div class="fw-bold">线下转账说明</div><div><?= nl2br(h($action['instructions'])) ?></div></div><form method="post" action="<?= h(url_to('index/pay/manual')) ?>"><?= csrf_field() ?><input type="hidden" name="payment_id" value="<?= (int)$pay['id'] ?>"><textarea name="remark" class="form-control mb-2" placeholder="填写付款时间、转账末四位或凭证说明" required></textarea><button class="btn btn-primary">提交付款说明</button></form><?php endif; ?><a class="btn btn-outline-primary mt-3" href="<?= h(url_to('index/order/index')) ?>">查看订单</a></div></section>
